   287→  /**
   288→   * Dirty hack - remove 'id' if it is present.
   289→   *
   290→   * @param node - the node to remove the coordinate from
   291→   * @return removed coordinate if it was removed
   292→   */
   293→  private String removeId(MappingNode node) {
   294→    NodeTuple id = null;
   295→    String scalar = null;
   296→    for (NodeTuple tuple : node.getValue()) {
   297→      ScalarNode keyNode = (ScalarNode) tuple.getKeyNode();
   298→      String key = keyNode.getValue();
   299→      if ("id".equals(key)) {
   300→        id = tuple;
   301→        ScalarNode valueNode = (ScalarNode) tuple.getValueNode();
   302→        scalar = valueNode.getValue();
   303→      }
   304→    }
   305→    if (id != null) {
   306→      node.getValue().remove(id);
   307→    }
   308→    return scalar;
   309→  }
