   170→  private static List<String> ORDER_MODEL = new ArrayList<String>(Arrays.asList(
   171→		  "modelEncoding",
   172→          "modelVersion",
   173→          "parent",
   174→          "groupId",
   175→          "artifactId",
   176→          "version",
